# Gunicorn settings for ProxySQL Web UI  (/etc/proxysql-webui/gunicorn.conf.py)
bind = "0.0.0.0:8443"

# TLS (self-signed certificate generated by the installer; replace with your own).
# Comment both lines out when running behind nginx/httpd on 127.0.0.1.
certfile = "/etc/proxysql-webui/tls/server.crt"
keyfile = "/etc/proxysql-webui/tls/server.key"

workers = 2
worker_class = "gthread"
threads = 4
timeout = 120
graceful_timeout = 20
accesslog = "-"
errorlog = "-"
loglevel = "info"
proc_name = "proxysql-webui"
forwarded_allow_ips = "127.0.0.1"
